public final class LimitParse {
    private LimitParse() {}

    private static final long I32_MAX = 2147483647L;

    private static boolean digit(char c) { return c >= '0' && c <= '9'; }

    private static String asciiLower(String s) {
        StringBuilder b = new StringBuilder();
        for (char c : s.toCharArray()) b.append(c >= 'A' && c <= 'Z' ? (char) (c + 32) : c);
        return b.toString();
    }

    public static long parseSize(String text) {
        int i = 0;
        while (i < text.length() && digit(text.charAt(i))) i++;
        if (i < 1 || i > 10) throw new IllegalArgumentException("bad size");
        long n = Long.parseLong(text.substring(0, i));
        long unit;
        switch (asciiLower(text.substring(i))) {
            case "": case "b": unit = 1; break;
            case "k": case "kb": case "kib": unit = 1L << 10; break;
            case "m": case "mb": case "mib": unit = 1L << 20; break;
            case "g": case "gb": case "gib": unit = 1L << 30; break;
            default: throw new IllegalArgumentException("bad unit");
        }
        long v = n * unit;
        if (v > I32_MAX) throw new ArithmeticException("too large");
        return v;
    }

    public static String fmtSize(int n) {
        if (n < 0) throw new IllegalArgumentException("negative");
        int[] sizes = {1 << 30, 1 << 20, 1 << 10};
        String[] names = {"G", "M", "K"};
        for (int k = 0; k < 3; k++) {
            if (n != 0 && n % sizes[k] == 0) return (n / sizes[k]) + names[k];
        }
        return Integer.toString(n);
    }

    public static long parseDur(String text) {
        if (text.isEmpty()) throw new IllegalArgumentException("bad duration");
        String units = "dhms";
        long[] mult = {86400, 3600, 60, 1};
        long total = 0;
        int next = 0;
        int i = 0;
        while (i < text.length()) {
            int j = i;
            while (j < text.length() && digit(text.charAt(j))) j++;
            if (j == i || j - i > 9 || j >= text.length()) throw new IllegalArgumentException("bad duration");
            int k = units.indexOf(text.charAt(j));
            if (k < next) throw new IllegalArgumentException("bad unit order");
            total += Long.parseLong(text.substring(i, j)) * mult[k];
            next = k + 1;
            i = j + 1;
        }
        if (total > I32_MAX) throw new ArithmeticException("too large");
        return total;
    }

    public static String fmtDur(int secs) {
        if (secs < 0) throw new IllegalArgumentException("negative");
        if (secs == 0) return "0s";
        long[] mult = {86400, 3600, 60, 1};
        String[] names = {"d", "h", "m", "s"};
        StringBuilder b = new StringBuilder();
        long rest = secs;
        for (int k = 0; k < 4; k++) {
            long q = rest / mult[k];
            if (q > 0) {
                b.append(q).append(names[k]);
                rest -= q * mult[k];
            }
        }
        return b.toString();
    }

    public static int addChecked(int a, int b) { return Math.addExact(a, b); }

    public static int mulChecked(int a, int b) { return Math.multiplyExact(a, b); }

    public static int absChecked(int a) {
        if (a == Integer.MIN_VALUE) throw new ArithmeticException("overflow");
        return Math.abs(a);
    }
}

start.TestMain.java:
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Function;

public class TestMain {
    static final Object UNKNOWN = new Object();

    // ---- minimal JSON reader: null, Boolean, Long, String, List<Object>, Map<String,Object> ----
    static final class Parser {
        final String s;
        int i = 0;
        Parser(String s) { this.s = s; }
        void ws() { while (i < s.length() && Character.isWhitespace(s.charAt(i))) i++; }
        Object value() {
            ws();
            char c = s.charAt(i);
            if (c == '"') return string();
            if (c == '[') {
                i++;
                List<Object> out = new ArrayList<>();
                ws();
                if (s.charAt(i) == ']') { i++; return out; }
                while (true) {
                    out.add(value());
                    ws();
                    char d = s.charAt(i++);
                    if (d == ']') return out;
                    if (d != ',') throw new IllegalStateException("bad array at " + i);
                }
            }
            if (c == '{') {
                i++;
                Map<String, Object> out = new LinkedHashMap<>();
                ws();
                if (s.charAt(i) == '}') { i++; return out; }
                while (true) {
                    ws();
                    String k = string();
                    ws();
                    if (s.charAt(i++) != ':') throw new IllegalStateException("expected ':' at " + i);
                    out.put(k, value());
                    ws();
                    char d = s.charAt(i++);
                    if (d == '}') return out;
                    if (d != ',') throw new IllegalStateException("bad object at " + i);
                }
            }
            if (s.startsWith("null", i)) { i += 4; return null; }
            if (s.startsWith("true", i)) { i += 4; return Boolean.TRUE; }
            if (s.startsWith("false", i)) { i += 5; return Boolean.FALSE; }
            int st = i;
            if (c == '-') i++;
            while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
            return Long.valueOf(s.substring(st, i));
        }
        String string() {
            if (s.charAt(i) != '"') throw new IllegalStateException("expected string at " + i);
            i++;
            StringBuilder b = new StringBuilder();
            while (true) {
                char c = s.charAt(i++);
                if (c == '"') return b.toString();
                if (c != '\\') { b.append(c); continue; }
                char e = s.charAt(i++);
                switch (e) {
                    case 'n': b.append('\n'); break;
                    case 't': b.append('\t'); break;
                    case 'r': b.append('\r'); break;
                    case 'b': b.append('\b'); break;
                    case 'f': b.append('\f'); break;
                    case 'u': b.append((char) Integer.parseInt(s.substring(i, i + 4), 16)); i += 4; break;
                    default: b.append(e);
                }
            }
        }
    }

    @SuppressWarnings("unchecked")
    static <T> List<T> list(Object v, Function<Object, T> f) {
        List<T> out = new ArrayList<>();
        for (Object x : (List<Object>) v) out.add(f.apply(x));
        return out;
    }

    static Object toJ(Object v) {
        if (v == null) return null;
        if (v instanceof Integer) return Long.valueOf((Integer) v);
        if (v instanceof Long || v instanceof Boolean || v instanceof String) return v;
        if (v instanceof List) {
            List<Object> out = new ArrayList<>();
            for (Object x : (List<?>) v) out.add(toJ(x));
            return out;
        }
        throw new IllegalStateException("unsupported result type " + v.getClass().getName());
    }

    static String show(Object v) {
        if (v == null) return "null";
        if (v instanceof String) {
            StringBuilder b = new StringBuilder("\"");
            for (char c : ((String) v).toCharArray()) {
                if (c == '"') b.append("\\\"");
                else if (c == '\\') b.append("\\\\");
                else if (c == '\n') b.append("\\n");
                else if (c < 0x20) b.append(String.format("\\u%04x", (int) c));
                else b.append(c);
            }
            return b.append('"').toString();
        }
        if (v instanceof List) {
            StringBuilder b = new StringBuilder("[");
            boolean first = true;
            for (Object x : (List<?>) v) {
                if (!first) b.append(',');
                first = false;
                b.append(show(x));
            }
            return b.append(']').toString();
        }
        return String.valueOf(v);
    }

    static Object call(String fn, List<Object> a) throws Exception {
        switch (fn) {
            case "parse_size": return LimitParse.parseSize((String) a.get(0));
            case "fmt_size": return LimitParse.fmtSize(((Long) a.get(0)).intValue());
            case "parse_dur": return LimitParse.parseDur((String) a.get(0));
            case "fmt_dur": return LimitParse.fmtDur(((Long) a.get(0)).intValue());
            case "add_checked": return LimitParse.addChecked(((Long) a.get(0)).intValue(), ((Long) a.get(1)).intValue());
            case "mul_checked": return LimitParse.mulChecked(((Long) a.get(0)).intValue(), ((Long) a.get(1)).intValue());
            case "abs_checked": return LimitParse.absChecked(((Long) a.get(0)).intValue());
            default: return UNKNOWN;
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        String path = Files.exists(Paths.get("vectors/full.json")) ? "vectors/full.json" : "vectors/examples.json";
        String text = new String(Files.readAllBytes(Paths.get(path)), StandardCharsets.UTF_8);
        Map<String, Object> doc = (Map<String, Object>) new Parser(text).value();
        List<Object> cases = (List<Object>) doc.get("cases");
        List<String> bad = new ArrayList<>();
        for (Object o : cases) {
            Map<String, Object> c = (Map<String, Object>) o;
            String fn = (String) c.get("fn");
            List<Object> a = (List<Object>) c.get("args");
            StringBuilder lb = new StringBuilder(fn).append('(');
            for (int k = 0; k < a.size(); k++) lb.append(k > 0 ? ", " : "").append(show(a.get(k)));
            String label = lb.append(')').toString();
            boolean isErr = Boolean.TRUE.equals(c.get("error"));
            Object got = null;
            boolean failed = false;
            try {
                got = call(fn, a);
                if (got == UNKNOWN) { bad.add("missing function " + fn); continue; }
                got = toJ(got);
            } catch (Throwable e) {
                failed = true;
            }
            if (isErr) {
                if (!failed) bad.add(label + ": expected an error, got " + show(got));
            } else if (failed) {
                bad.add(label + ": unexpected error, want " + show(c.get("want")));
            } else if (!Objects.equals(got, c.get("want"))) {
                bad.add(label + ": want " + show(c.get("want")) + ", got " + show(got));
            }
        }
        if (!bad.isEmpty()) {
            System.out.println(bad.size() + " of " + cases.size() + " vectors failed:");
            for (int k = 0; k < Math.min(8, bad.size()); k++) System.out.println("  " + bad.get(k));
            System.exit(1);
        }
        System.out.println("ok " + cases.size() + " vectors");
    }
}

