package limitparse

import (
	"errors"
	"strconv"
	"strings"
)

const i32Max = 2147483647

var errBad = errors.New("limitparse: bad input")
var errOverflow = errors.New("limitparse: does not fit in 32 bits")

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func asciiLower(s string) string {
	b := []byte(s)
	for i, c := range b {
		if c >= 'A' && c <= 'Z' {
			b[i] = c + 32
		}
	}
	return string(b)
}

func ParseSize(text string) (int64, error) {
	i := 0
	for i < len(text) && isDigit(text[i]) {
		i++
	}
	if i < 1 || i > 10 {
		return 0, errBad
	}
	n, err := strconv.ParseInt(text[:i], 10, 64)
	if err != nil {
		return 0, errBad
	}
	var unit int64
	switch asciiLower(text[i:]) {
	case "", "b":
		unit = 1
	case "k", "kb", "kib":
		unit = 1 << 10
	case "m", "mb", "mib":
		unit = 1 << 20
	case "g", "gb", "gib":
		unit = 1 << 30
	default:
		return 0, errBad
	}
	v := n * unit
	if v > i32Max {
		return 0, errOverflow
	}
	return v, nil
}

func FmtSize(n int32) (string, error) {
	if n < 0 {
		return "", errBad
	}
	for _, u := range []struct {
		size int32
		name string
	}{{1 << 30, "G"}, {1 << 20, "M"}, {1 << 10, "K"}} {
		if n != 0 && n%u.size == 0 {
			return strconv.Itoa(int(n/u.size)) + u.name, nil
		}
	}
	return strconv.Itoa(int(n)), nil
}

func ParseDur(text string) (int64, error) {
	if text == "" {
		return 0, errBad
	}
	units := []byte{'d', 'h', 'm', 's'}
	mult := map[byte]int64{'d': 86400, 'h': 3600, 'm': 60, 's': 1}
	var total int64
	next := 0 // index of the first unit still allowed
	i := 0
	for i < len(text) {
		j := i
		for j < len(text) && isDigit(text[j]) {
			j++
		}
		if j == i || j-i > 9 || j >= len(text) {
			return 0, errBad
		}
		u := text[j]
		k := next
		for k < len(units) && units[k] != u {
			k++
		}
		if k == len(units) {
			return 0, errBad
		}
		n, _ := strconv.ParseInt(text[i:j], 10, 64)
		total += n * mult[u]
		next = k + 1
		i = j + 1
	}
	if total > i32Max {
		return 0, errOverflow
	}
	return total, nil
}

func FmtDur(secs int32) (string, error) {
	if secs < 0 {
		return "", errBad
	}
	if secs == 0 {
		return "0s", nil
	}
	var b strings.Builder
	rest := int64(secs)
	for _, p := range []struct {
		mult int64
		unit string
	}{{86400, "d"}, {3600, "h"}, {60, "m"}, {1, "s"}} {
		if q := rest / p.mult; q > 0 {
			b.WriteString(strconv.FormatInt(q, 10) + p.unit)
			rest -= q * p.mult
		}
	}
	return b.String(), nil
}

func AddChecked(a, b int32) (int32, error) {
	s := int64(a) + int64(b)
	if s > i32Max || s < -2147483648 {
		return 0, errOverflow
	}
	return int32(s), nil
}

func MulChecked(a, b int32) (int32, error) {
	p := int64(a) * int64(b)
	if p > i32Max || p < -2147483648 {
		return 0, errOverflow
	}
	return int32(p), nil
}

func AbsChecked(a int32) (int32, error) {
	if a == -2147483648 {
		return 0, errOverflow
	}
	if a < 0 {
		return -a, nil
	}
	return a, nil
}

